"=== WINGET ==="; if(Get-Command winget -ErrorAction SilentlyContinue){ winget --version 2>&1 | Select-Object -First 1; winget search --id Google.AndroidStudio --exact 2>&1 | Select-Object -First 4 } else { "winget NOT FOUND" }
"=== ADMIN ==="; ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
"=== STUDIO PRESENT ==="; Test-Path "C:\Program Files\Android\Android Studio\bin\studio64.exe"
